from datetime import datetime, date, timedelta
import calendar
from functools import lru_cache

_FREQS = {"daily", "weekly", "monthly", "yearly"}
_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _parse_local(s: str) -> datetime:
    if s.endswith("Z"):
        s = s[:-1]
    return datetime.strptime(s, "%Y-%m-%dT%H:%M")


def _parse_utc(s: str) -> datetime:
    if s.endswith("Z"):
        s = s[:-1]
    return datetime.strptime(s, "%Y-%m-%dT%H:%M")


def _fmt_utc(dt: datetime) -> str:
    return f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}T{dt.hour:02d}:{dt.minute:02d}Z"


def _ceil_multiple(n: int, k: int) -> int:
    if n <= 0:
        return 0
    return ((n + k - 1) // k) * k


@lru_cache(maxsize=8192)
def _month_dates(y, m, month_day_pattern, nth_pattern):
    if nth_pattern is not None:
        n, wd = nth_pattern
        days_in_month = calendar.monthrange(y, m)[1]
        first = date(y, m, 1)
        first_day = 1 + ((wd - first.weekday()) % 7)
        total = (days_in_month - first_day) // 7 + 1

        if n > 0:
            if 1 <= n <= total:
                return (date(y, m, first_day + (n - 1) * 7),)
            return ()
        else:
            k = -n
            if 1 <= k <= total:
                return (date(y, m, first_day + (total - k) * 7),)
            return ()

    if not month_day_pattern:
        return ()

    days_in_month = calendar.monthrange(y, m)[1]
    days = set()

    for d in month_day_pattern:
        if 1 <= d <= 31:
            if d <= days_in_month:
                days.add(d)
        elif -31 <= d <= -1:
            mapped = days_in_month + d + 1
            if 1 <= mapped <= days_in_month:
                days.add(mapped)

    return tuple(date(y, m, day) for day in sorted(days))


def _iter_daily(interval, start_date, lower_date, upper_date):
    if lower_date > upper_date:
        return
    if lower_date < start_date:
        lower_date = start_date

    delta = (lower_date - start_date).days
    rem = delta % interval

    if rem:
        days_ahead = interval - rem
        if days_ahead > (upper_date - lower_date).days:
            return
        d = lower_date + timedelta(days=days_ahead)
    else:
        d = lower_date

    while d <= upper_date:
        yield d
        if (upper_date - d).days < interval:
            break
        d += timedelta(days=interval)


def _iter_weekly(interval, start_date, weekdays, lower_date, upper_date):
    if lower_date > upper_date:
        return
    if lower_date < start_date:
        lower_date = start_date

    week0 = start_date - timedelta(days=start_date.weekday())
    idx_lower = (lower_date - week0).days // 7
    idx_upper = (upper_date - week0).days // 7

    if idx_lower < 0:
        idx_lower = 0
    if idx_upper < 0:
        return

    first = _ceil_multiple(idx_lower, interval)
    if first > idx_upper:
        return

    for wi in range(first, idx_upper + 1, interval):
        monday = week0 + timedelta(days=wi * 7)
        for wd in weekdays:
            d = monday + timedelta(days=wd)
            if d < lower_date:
                continue
            if d > upper_date:
                break
            yield d


def _iter_monthly(
    interval,
    start_date,
    start_year,
    start_month,
    month_day_pattern,
    nth_pattern,
    lower_date,
    upper_date,
):
    if lower_date > upper_date:
        return
    if lower_date < start_date:
        lower_date = start_date

    def month_index(d):
        return (d.year - start_year) * 12 + (d.month - start_month)

    idx_lower = month_index(lower_date)
    idx_upper = month_index(upper_date)

    if idx_lower < 0:
        idx_lower = 0
    if idx_upper < 0:
        return

    first = _ceil_multiple(idx_lower, interval)
    if first > idx_upper:
        return

    base = start_year * 12 + (start_month - 1)
    for mi in range(first, idx_upper + 1, interval):
        total = base + mi
        y, m0 = divmod(total, 12)
        m = m0 + 1

        for d in _month_dates(y, m, month_day_pattern, nth_pattern):
            if d < lower_date:
                continue
            if d > upper_date:
                break
            yield d


def _iter_yearly(interval, start_date, start_month, start_day, lower_date, upper_date):
    if lower_date > upper_date:
        return
    if lower_date < start_date:
        lower_date = start_date

    start_year = start_date.year

    if lower_date <= start_date:
        first_year = start_year
    elif lower_date.year == start_year:
        first_year = start_year + interval
    else:
        y = lower_date.year
        rem = (y - start_year) % interval
        first_year = y if rem == 0 else y + (interval - rem)

    last_year = upper_date.year
    if first_year > last_year:
        return

    for y in range(first_year, last_year + 1, interval):
        try:
            d = date(y, start_month, start_day)
        except ValueError:
            continue
        if d < lower_date or d > upper_date:
            continue
        yield d


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    freq = rule.get("freq")
    if freq not in _FREQS:
        raise ValueError("unknown freq")

    interval = rule.get("interval", 1)
    if interval < 1:
        raise ValueError("interval must be at least 1")

    if "count" in rule and "until" in rule:
        raise ValueError("count and until cannot both be present")

    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError("by_month_day and by_nth_weekday cannot both be present")

    offset_minutes = rule["utc_offset_minutes"]
    offset_delta = timedelta(minutes=offset_minutes)

    start_local = _parse_local(rule["start"])
    start_date = start_local.date()
    start_time = start_local.time()

    count = rule.get("count")
    if count is not None and count <= 0:
        return []

    until_local = _parse_local(rule["until"]) if "until" in rule else None

    exclude_dates = set()
    for s in rule.get("exclude", ()):
        e = _parse_local(s)
        if e.time() == start_time:
            exclude_dates.add(e.date())

    window_start_local = _parse_utc(window_start) + offset_delta
    window_end_local = _parse_utc(window_end) + offset_delta

    weekdays = ()
    month_day_pattern = None
    nth_pattern = None

    if freq == "weekly":
        raw = rule.get("by_weekday")
        if raw is None:
            weekdays = (start_date.weekday(),)
        else:
            weekdays = tuple(sorted({_WEEKDAYS[d] for d in raw}))

    elif freq == "monthly":
        if "by_nth_weekday" in rule:
            n, wd = rule["by_nth_weekday"]
            nth_pattern = (n, _WEEKDAYS[wd])
        else:
            raw_days = rule.get("by_month_day")
            if raw_days is None:
                month_day_pattern = (start_date.day,)
            else:
                month_day_pattern = tuple(raw_days)

    def iter_dates(lower_date, upper_date):
        if lower_date > upper_date:
            return

        if freq == "daily":
            yield from _iter_daily(interval, start_date, lower_date, upper_date)
        elif freq == "weekly":
            yield from _iter_weekly(interval, start_date, weekdays, lower_date, upper_date)
        elif freq == "monthly":
            yield from _iter_monthly(
                interval,
                start_date,
                start_date.year,
                start_date.month,
                month_day_pattern,
                nth_pattern,
                lower_date,
                upper_date,
            )
        else:
            yield from _iter_yearly(
                interval,
                start_date,
                start_date.month,
                start_date.day,
                lower_date,
                upper_date,
            )

    if count is None:
        lower_local = window_start_local if window_start_local > start_local else start_local
        upper_local = window_end_local

        if until_local is not None:
            until_upper = until_local + timedelta(minutes=1)
            if until_upper < upper_local:
                upper_local = until_upper

        if upper_local <= lower_local:
            return []

        out = []
        for d in iter_dates(lower_local.date(), upper_local.date()):
            dt = datetime.combine(d, start_time)
            if dt < lower_local or dt >= upper_local:
                continue
            if d in exclude_dates:
                continue
            out.append(_fmt_utc(dt - offset_delta))
        return out

    upper_local = window_end_local
    if upper_local <= start_local:
        return []

    out = []
    used = 0

    for d in iter_dates(start_date, upper_local.date()):
        dt = datetime.combine(d, start_time)

        if dt < start_local:
            continue
        if dt >= upper_local:
            break

        used += 1

        if d in exclude_dates:
            pass
        elif dt >= window_start_local:
            out.append(_fmt_utc(dt - offset_delta))

        if used >= count:
            break

    return out
